<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Maintenance','subtitle'=>'Track unavailable quantities, repairs, inspections, and completion.']) ?><div class="grid-2 uneven"><section class="panel"><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Type</th><th>Qty</th><th>Dates</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= esc($r['equipment_name']) ?></b><small><?= esc($r['asset_code']) ?></small></td><td><?= esc($r['maintenance_type']) ?><small><?= esc($r['description']) ?></small></td><td><?= (int)$r['quantity'] ?></td><td><?= esc(fmt_date($r['start_date'])) ?><small>Done: <?= esc(fmt_date($r['completion_date'])) ?></small></td><td><?= view('partials/status_badge',['status'=>$r['status']]) ?></td><td><?php if(!in_array($r['status'],['completed','cancelled'],true)): ?><form method="post" action="<?= site_url('maintenance/'.$r['id'].'/status') ?>" class="inline-form" data-confirm="Update maintenance status for <?= esc($r['equipment_name'],'attr') ?>?"><?= csrf_field() ?><select name="status"><?php foreach(config('BantayGamit')->maintenanceStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $r['status']===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><button class="btn small" type="submit">Update</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(empty($rows)): ?><tr><td colspan="6"><div class="empty">No maintenance records.</div></td></tr><?php endif; ?></tbody></table></div></section><aside class="panel action-panel"><h2>New Maintenance Record</h2><form method="post" action="<?= site_url('maintenance') ?>" class="stack-form"><?= csrf_field() ?><label>Equipment<select name="equipment_id" required><option value="">Select equipment</option><?php foreach($equipment as $e): ?><option value="<?= $e['id'] ?>" <?= (string)old('equipment_id')===(string)$e['id']?'selected':'' ?>><?= esc($e['asset_code'].' · '.$e['name'].' ('.$e['available_quantity'].' available)') ?></option><?php endforeach; ?></select></label><label>Maintenance Type<input name="maintenance_type" value="<?= esc(old('maintenance_type')) ?>" required placeholder="Repair, inspection, cleaning..."></label><label>Quantity<input type="number" min="1" name="quantity" value="<?= esc(old('quantity','1')) ?>" required></label><label>Status<select name="status"><?php foreach(['reported'=>'Reported','scheduled'=>'Scheduled','in_progress'=>'In Progress'] as $k=>$v): ?><option value="<?= esc($k) ?>" <?= old('status','reported')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" rows="3" required><?= esc(old('description')) ?></textarea></label><label>Start Date<input type="date" name="start_date" value="<?= esc(old('start_date')) ?>"></label><label>Cost<input type="number" step="0.01" min="0" name="cost" value="<?= esc(old('cost')) ?>"></label><label>Notes<textarea name="notes" rows="2"><?= esc(old('notes')) ?></textarea></label><button class="btn primary wide" type="submit">Create Record</button></form></aside></div><?= $this->endSection() ?>
